<?php
require dirname(__DIR__).'/includes/bootstrap.php';require_permission('employees.manage');verify_csrf();$eid=(int)($_POST['id']??0);$pdo=db();$q=$pdo->prepare('SELECT e.user_id,u.account_status,r.slug role_slug FROM employees e LEFT JOIN users u ON u.id=e.user_id LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id WHERE e.id=?');$q->execute([$eid]);$row=$q->fetch();if(!$row){flash('error','Employee not found.');redirect('employees.php');}if((int)$row['user_id']===current_user_id()){flash('error','You cannot deactivate your own account.');redirect('employees.php');}if($row['role_slug']==='super_admin'&&$row['account_status']==='active'){$count=(int)$pdo->query("SELECT COUNT(DISTINCT u.id) FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE r.slug='super_admin' AND u.account_status='active'")->fetchColumn();if($count<=1){flash('error','The last active Super Administrator cannot be deactivated.');redirect('employees.php');}}$new=$row['account_status']==='active'?'inactive':'active';$pdo->prepare('UPDATE users SET account_status=? WHERE id=?')->execute([$new,$row['user_id']]);$pdo->prepare('UPDATE employees SET employment_status=? WHERE id=?')->execute([$new==='active'?'active':'inactive',$eid]);audit('employee.status_changed','employee',$eid,['status'=>$new]);flash('success','Employee status updated.');redirect('employees.php');
